-- Selected existing ChurchApps Plans contracts on normalized D1 tables.
CREATE TABLE doing_plan_types (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), ministryId TEXT NOT NULL, name TEXT NOT NULL, lessonTrim TEXT, UNIQUE(churchId,id), FOREIGN KEY(churchId,ministryId) REFERENCES groups(churchId,id));
CREATE TABLE doing_plans (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), ministryId TEXT NOT NULL, campusId TEXT, planTypeId TEXT, name TEXT NOT NULL, serviceDate TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', serviceOrder INTEGER NOT NULL DEFAULT 0 CHECK(serviceOrder IN(0,1)), signupDeadlineHours INTEGER, showVolunteerNames INTEGER NOT NULL DEFAULT 0 CHECK(showVolunteerNames IN(0,1)), prepared INTEGER NOT NULL DEFAULT 0 CHECK(prepared IN(0,1)), autoReplaceOnDecline INTEGER NOT NULL DEFAULT 0 CHECK(autoReplaceOnDecline=0), contentType TEXT, contentId TEXT, providerId TEXT, providerPlanId TEXT, providerPlanName TEXT, lastAutofillRunId TEXT, confirmationWorkflowId TEXT, lessonTrimWarning TEXT, UNIQUE(churchId,id), FOREIGN KEY(churchId,ministryId) REFERENCES groups(churchId,id), FOREIGN KEY(churchId,planTypeId) REFERENCES doing_plan_types(churchId,id));
CREATE INDEX doing_plans_dates ON doing_plans(churchId,serviceDate);
CREATE TABLE doing_positions (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), planId TEXT NOT NULL, categoryName TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 1 CHECK(typeof(count)='integer' AND count>=0 AND count<=100), groupId TEXT, allowSelfSignup INTEGER NOT NULL DEFAULT 0 CHECK(allowSelfSignup IN(0,1)), description TEXT NOT NULL DEFAULT '', UNIQUE(churchId,id), UNIQUE(churchId,planId,id), FOREIGN KEY(churchId,planId) REFERENCES doing_plans(churchId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,groupId) REFERENCES groups(churchId,id));
CREATE TABLE doing_times (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), planId TEXT NOT NULL, displayName TEXT NOT NULL, startTime TEXT NOT NULL, endTime TEXT NOT NULL, teams TEXT NOT NULL DEFAULT '', serviceTimeType TEXT NOT NULL DEFAULT 'service', CHECK(endTime>startTime), UNIQUE(churchId,id), FOREIGN KEY(churchId,planId) REFERENCES doing_plans(churchId,id) ON DELETE CASCADE);
CREATE INDEX doing_times_plan ON doing_times(churchId,planId);
CREATE TABLE doing_assignments (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), positionId TEXT NOT NULL, personId TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Unconfirmed' CHECK(status IN('Unconfirmed','Accepted','Declined')), notified TEXT, autofillRunId TEXT, confirmationWorkflowId TEXT, UNIQUE(churchId,id), UNIQUE(churchId,positionId,personId), FOREIGN KEY(churchId,positionId) REFERENCES doing_positions(churchId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,personId) REFERENCES people(churchId,id));
CREATE INDEX doing_assignments_person ON doing_assignments(churchId,personId);
CREATE TABLE doing_plan_items (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), planId TEXT NOT NULL, parentId TEXT, sort REAL NOT NULL DEFAULT 0, itemType TEXT NOT NULL DEFAULT 'item', actionType TEXT, relatedId TEXT, positionId TEXT, label TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', seconds INTEGER NOT NULL DEFAULT 0 CHECK(typeof(seconds)='integer' AND seconds>=0 AND seconds<=86400), link TEXT, providerId TEXT, providerPath TEXT, providerContentPath TEXT, thumbnailUrl TEXT, UNIQUE(churchId,id), UNIQUE(churchId,planId,id), CHECK(parentId IS NULL OR parentId<>id), FOREIGN KEY(churchId,planId) REFERENCES doing_plans(churchId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,planId,parentId) REFERENCES doing_plan_items(churchId,planId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,planId,positionId) REFERENCES doing_positions(churchId,planId,id));
CREATE INDEX doing_plan_items_plan ON doing_plan_items(churchId,planId,parentId,sort);
CREATE TABLE doing_plan_item_times (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), planItemId TEXT NOT NULL, timeId TEXT NOT NULL, excluded INTEGER NOT NULL DEFAULT 0 CHECK(excluded IN(0,1)), positionId TEXT, UNIQUE(churchId,id), UNIQUE(churchId,planItemId,timeId), FOREIGN KEY(churchId,planItemId) REFERENCES doing_plan_items(churchId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,timeId) REFERENCES doing_times(churchId,id) ON DELETE CASCADE, FOREIGN KEY(churchId,positionId) REFERENCES doing_positions(churchId,id));
CREATE TABLE doing_blockout_dates (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), personId TEXT NOT NULL, startDate TEXT NOT NULL, endDate TEXT NOT NULL, CHECK(endDate>=startDate), UNIQUE(churchId,id), FOREIGN KEY(churchId,personId) REFERENCES people(churchId,id));
CREATE INDEX doing_blockouts_person ON doing_blockout_dates(churchId,personId,startDate,endDate);
CREATE TABLE doing_scheduling_preferences (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), personId TEXT NOT NULL, maxPerMonth INTEGER NOT NULL DEFAULT 0 CHECK(typeof(maxPerMonth)='integer' AND maxPerMonth>=0 AND maxPerMonth<=100), preferredTimes TEXT NOT NULL DEFAULT '', householdScheduling TEXT NOT NULL DEFAULT 'none' CHECK(householdScheduling IN('none','together','apart')), UNIQUE(churchId,id), UNIQUE(churchId,personId), FOREIGN KEY(churchId,personId) REFERENCES people(churchId,id));
-- Cross-plan exclusions and cyclic service-order trees must not be created by a request race.
CREATE TRIGGER doing_item_cycle BEFORE UPDATE OF parentId ON doing_plan_items WHEN NEW.parentId IS NOT NULL BEGIN SELECT CASE WHEN EXISTS(WITH RECURSIVE ancestors(id,parentId) AS (SELECT id,parentId FROM doing_plan_items WHERE churchId=NEW.churchId AND id=NEW.parentId UNION SELECT p.id,p.parentId FROM doing_plan_items p JOIN ancestors a ON p.id=a.parentId WHERE p.churchId=NEW.churchId) SELECT 1 FROM ancestors WHERE id=NEW.id) THEN RAISE(ABORT,'Service order cycle') END; END;
CREATE TRIGGER doing_item_time_insert BEFORE INSERT ON doing_plan_item_times WHEN NOT EXISTS(SELECT 1 FROM doing_plan_items i JOIN doing_times t ON t.churchId=i.churchId AND t.planId=i.planId WHERE i.churchId=NEW.churchId AND i.id=NEW.planItemId AND t.id=NEW.timeId AND (NEW.positionId IS NULL OR EXISTS(SELECT 1 FROM doing_positions p WHERE p.churchId=i.churchId AND p.planId=i.planId AND p.id=NEW.positionId))) BEGIN SELECT RAISE(ABORT,'Plan item time mismatch'); END;
CREATE TRIGGER doing_item_time_update BEFORE UPDATE ON doing_plan_item_times WHEN NOT EXISTS(SELECT 1 FROM doing_plan_items i JOIN doing_times t ON t.churchId=i.churchId AND t.planId=i.planId WHERE i.churchId=NEW.churchId AND i.id=NEW.planItemId AND t.id=NEW.timeId AND (NEW.positionId IS NULL OR EXISTS(SELECT 1 FROM doing_positions p WHERE p.churchId=i.churchId AND p.planId=i.planId AND p.id=NEW.positionId))) BEGIN SELECT RAISE(ABORT,'Plan item time mismatch'); END;
ALTER TABLE doing_assignments ADD COLUMN selfSignup INTEGER NOT NULL DEFAULT 0 CHECK(selfSignup IN(0,1));
CREATE TRIGGER doing_self_signup_insert BEFORE INSERT ON doing_assignments WHEN NEW.selfSignup=1 AND NEW.status<>'Declined' BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM doing_positions p JOIN doing_plans pl ON pl.churchId=p.churchId AND pl.id=p.planId WHERE p.churchId=NEW.churchId AND p.id=NEW.positionId AND p.allowSelfSignup=1 AND pl.prepared=0 AND pl.serviceDate>=date('now') AND (pl.signupDeadlineHours IS NULL OR pl.signupDeadlineHours=0 OR julianday('now')<julianday(COALESCE((SELECT MIN(t.startTime) FROM doing_times t WHERE t.churchId=pl.churchId AND t.planId=pl.id),pl.serviceDate))-pl.signupDeadlineHours/24.0) AND (SELECT COUNT(*) FROM doing_assignments a WHERE a.churchId=p.churchId AND a.positionId=p.id AND a.status<>'Declined')<p.count) THEN RAISE(ABORT,'Signup is closed or position is full') END; END;
CREATE TRIGGER doing_self_signup_update BEFORE UPDATE OF status,positionId ON doing_assignments WHEN NEW.selfSignup=1 AND NEW.status<>'Declined' BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM doing_assignments a WHERE a.churchId=NEW.churchId AND a.positionId=NEW.positionId AND a.status<>'Declined' AND a.id<>NEW.id)>=(SELECT count FROM doing_positions WHERE churchId=NEW.churchId AND id=NEW.positionId) THEN RAISE(ABORT,'Position is full') END; END;
CREATE TRIGGER doing_assignment_person_insert BEFORE INSERT ON doing_assignments WHEN NOT EXISTS(SELECT 1 FROM people WHERE churchId=NEW.churchId AND id=NEW.personId AND removed=0) BEGIN SELECT RAISE(ABORT,'Inactive assignee'); END;
CREATE TRIGGER doing_assignment_person_update BEFORE UPDATE OF personId,status ON doing_assignments WHEN NEW.status<>'Declined' AND NOT EXISTS(SELECT 1 FROM people WHERE churchId=NEW.churchId AND id=NEW.personId AND removed=0) BEGIN SELECT RAISE(ABORT,'Inactive assignee'); END;
